public static String base64Decode(final String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null.");
    }

    if (!s.matches("[A-Za-z0-9+/=]*")) {
        throw new IllegalArgumentException("Input string is not a valid Base64 encoding.");
    }

    // Replace '+' with '-', '/' with '_', and '=' with '*'
    String replaced = s.replace('+', '-').replace('/', '_').replace('=', '*');

    // Decode the Base64-encoded string
    byte[] decoded = DatatypeConverter.parseBase64Binary(replaced);

    // Return the decoded string
    return new String(decoded);
}

