void pop(String descriptor) {
    // Handle invalid input
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }

    // Parse the descriptor to get the number of types to pop
    Type[] types;
    try {
        types = Type.getArgumentTypes(descriptor);
    } catch (Exception e) {
        throw new RuntimeException("Error parsing descriptor", e);
    }

    // Pop each type from the output frame stack
    for (int i = 0; i < types.length; i++) {
        Type t = types[i];
        if (t.getSize() > 0) {
            // Pop the value from the output frame stack
            Object value = getOutputFrame().pop();

            // Check if the popped value is of the correct type, and throw an exception if it is not
            if (!value.getClass().isAssignableFrom(t.getClazz())) {
                throw new IllegalStateException("Expected value of type " + t + ", but found " + value);
            }
        }
    }
}

