public boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> previous = node.previous;
    ListNodeImpl<E> next = node.next;

    if (previous == null) {
        // node is the first node in the list, unlink it from the list
        next.previous = null;
        head = next;
    } else if (next == null) {
        // node is the last node in the list, unlink it from the list
        previous.next = null;
        tail = previous;
    } else {
        // node is an inner node in the list, unlink it from the list
        previous.next = next;
        next.previous = previous;
    }

    node.previous = null;
    node.next = null;

    size--;

    return true;
}

