    // Check if the input is valid
    if (from < 0 || to < from || to >= arr.length) {
        throw new IllegalArgumentException("Invalid range specified");
    }

    // Reverse the elements in the range
    for (int i = from, j = to; i < j; i++, j--) {
        V tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

