@Override
    public void map(Graph<V, E> graph) throws InvalidInputException {
        // Check if the input graph is valid
        if (graph == null || graph.getNumVertices() == 0) {
            throw new InvalidInputException("Input graph is null or has no vertices.");
        }

        // Create a new mapping
        IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>(graph, graph);

        // Create a queue to store vertices to process
        Queue<V> queue = new LinkedList<>();

        // Add all vertices to the queue
        for (V vertex : graph.getVertices()) {
            queue.add(vertex);
        }

        // Breadth-first search to find the identity automorphism
        while (!queue.isEmpty()) {
            V vertex = queue.remove();
            E edge = graph.getEdge(vertex, vertex);
            if (edge == null) {
                throw new InvalidInputException("Input graph is not connected.");
            }
            mapping.add(vertex, vertex, edge);
            for (E outEdge : graph.getOutEdges(vertex)) {
                V neighbor = graph.getNeighbor(vertex, outEdge);
                mapping.add(vertex, neighbor, outEdge);
                queue.add(neighbor);
            }
        }

        return mapping;
    }
}

