private List<Integer> computeUpperBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("List of keys is null or empty");
    }

    // Initialize the upper bounds with the maximum integer value
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        upperBounds.add(Integer.MAX_VALUE);
    }

    // For each key, find the minimum lower bound and update the upper bound
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        // Find the minimum lower bound for the current key
        int minLowerBound = computeMinLowerBound(key);
        // Update the upper bound for the current key
        upperBounds.set(i, Math.min(upperBounds.get(i), minLowerBound));
    }

    return upperBounds;
}

