private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (i < bb.limit() && bb.get(i) < 128) { // while there are more bytes to decode and the byte is a single-byte ASCII character
        sb.append((char)(bb.get(i) & 0xFF)); // append the byte as a single-byte ASCII character
        i++;
    }
    if (i == bb.limit()) { // if there are no more bytes to decode
        return i;
    }
    if (bb.get(i) >= 192 && bb.get(i) <= 223) { // if the byte is a continuation byte
        sb.append((char)(((bb.get(i) & 0x1F) << 6) | (bb.get(i + 1) & 0x3F))); // append the 2-byte character
        return i + 2;
    }
    if (bb.get(i) <= 239 && bb.get(i) >= 184) { // if the byte is a possible start of a 3-byte character
        if (i + 2 < bb.limit() && (bb.get(i + 1) & 0xC0) == 0x80 && (bb.get(i + 2) & 0xC0) == 0x80) { // check if the next 2 bytes are continuation bytes
            sb.append((char)(((bb.get(i) & 0x0F) << 12) | ((bb.get(i + 1) & 0x3F) << 6) | (bb.get(i + 2) & 0x3F))); // append the 3-byte character
            return i + 3;
        } else { // if the next 2 bytes are not continuation bytes
            throw new InvalidPrefixException(); // throw an exception
        }
    }
    return i;
}

