    Level level = event.getLevel();
    if (level == Level.ERROR || level == Level.FATAL) {
        return Filter.ACCEPT;
    } else if (level == Level.WARN) {
        return Filter.NEUTRAL;
    } else {
        return Filter.DENY;
    }
}

