public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    long fetchDataDuration = FETCH_DATA_DURATION;

    // If the start time is less than the fetch data duration,
    // generate a TimeRange for the remaining amount of time
    if (start < fetchDataDuration) {
        timeRanges.add(new TimeRange(start, fetchDataDuration));
        start = 0;
    }

    // If the end time is greater than the fetch data duration,
    // split the range into two TimeRanges
    if (end > fetchDataDuration) {
        timeRanges.add(new TimeRange(start, fetchDataDuration));
        timeRanges.add(new TimeRange(0, end - fetchDataDuration));
    }

    return timeRanges;
}

