public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the epoch day for the given time bucket
    long epochDay = timeBucket / 10000;

    // Calculate the day offset for the given day step
    int dayOffset = dayStep % 10;

    // Calculate the day of the month for the given time bucket
    int dayOfMonth = (int) ((timeBucket % 10000) / 100);

    // Calculate the new epoch day based on the day offset and day of the month
    long newEpochDay = epochDay + dayOffset - dayOfMonth;

    // Return the new epoch day as the compressed time bucket
    return newEpochDay * 10000;
}

