        int currentSnapshotIndex = 0;
        while (currentSnapshotIndex < currentProfile.getSnapshots().size()) {
            Snapshot currentSnapshot = currentProfile.getSnapshots().get(currentSnapshotIndex);
            int numSnapshotSegments = currentSnapshot.getSegments().size();
            if (numSnapshotSegments > 0) {
