LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    // Check if the string is null or empty
    if (str == null || str.length() == 0) {
        // Write a null byte to indicate the end of the string
        lb.data().writeByte(0);
        return lb;
    }

    // Get the number of characters in the string
    int len = str.length();

    // Write the length of the string in bytes, not including the null terminator
    lb.data().writeShort(len);

    // Write the bytes of the string
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        lb.data().writeByte(c);
    }

    // Write the null terminator
    lb.data().writeByte(0);

    return lb;
}

